<?php
require "db.php";
$sql="SELECT b.*,f.name AS farmer_name,COALESCE(p.extra_paid,0) AS extra_paid FROM bills b JOIN farmers f ON f.id=b.farmer_id LEFT JOIN (SELECT bill_id,SUM(amount) extra_paid FROM bill_payments GROUP BY bill_id) p ON p.bill_id=b.id ORDER BY b.id DESC";
$result=$conn->query($sql);
